import { MakeLogicType, actions, connect, kea, key, listeners, path, props, reducers } from 'kea'
import posthog from 'posthog-js'

import { emailDomainAutoConfigureLogic } from './emailDomainAutoConfigureLogic'
import { EmailDomainLogicProps } from './emailDomainLogicProps'
import { EmailSetupMethod, emailDomainSenderLogic } from './emailDomainSenderLogic'
import { emailDomainStatusLogic } from './emailDomainStatusLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface emailDomainManualSetupLogicValues {
    domain: string | null // emailDomainSenderLogic
    manualSetupRecorded: boolean
    recordsAdded: boolean
    recordsRevealed: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface emailDomainManualSetupLogicActions {
    openAutoConfigure: () => {
        value: true
    } // emailDomainAutoConfigureLogic
    recordSetupMethod: (method: EmailSetupMethod) => {
        method: EmailSetupMethod
    } // emailDomainSenderLogic
    recheck: () => {
        value: true
    } // emailDomainStatusLogic
    markRecordsAdded: () => {
        value: true
    }
    recordManualSetup: () => {
        value: true
    }
    revealRecords: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface emailDomainManualSetupLogicMeta {
    key: string
}

export type emailDomainManualSetupLogicType = MakeLogicType<
    emailDomainManualSetupLogicValues,
    emailDomainManualSetupLogicActions,
    EmailDomainLogicProps,
    emailDomainManualSetupLogicMeta
>

/** The path where the person adds the DNS records by hand: reveals them, marks them added and records that method once. */
export const emailDomainManualSetupLogic = kea<emailDomainManualSetupLogicType>([
    path((key) => ['products', 'workflows', 'frontend', 'Channels', 'EmailDomain', 'emailDomainManualSetupLogic', key]),
    props({} as EmailDomainLogicProps),
    key(({ id }) => id),
    connect((props: EmailDomainLogicProps) => ({
        values: [emailDomainSenderLogic(props), ['domain']],
        actions: [
            emailDomainSenderLogic(props),
            ['recordSetupMethod'],
            emailDomainStatusLogic(props),
            ['recheck'],
            emailDomainAutoConfigureLogic(props),
            ['openAutoConfigure'],
        ],
    })),
    actions({
        revealRecords: true,
        markRecordsAdded: true,
        recordManualSetup: true,
    }),
    reducers({
        recordsRevealed: [
            false,
            {
                revealRecords: () => true,
                markRecordsAdded: () => true,
            },
        ],
        recordsAdded: [
            false,
            {
                markRecordsAdded: () => true,
            },
        ],
        // Auto-configure writes `auto` on the backend, so a later manual step must be recorded again.
        manualSetupRecorded: [
            false,
            {
                recordSetupMethod: (_, { method }) => method === 'manual',
                openAutoConfigure: () => false,
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        revealRecords: () => {
            actions.recordManualSetup()
        },
        markRecordsAdded: () => {
            // pinned: analytics event name
            posthog.capture('email domain records added', { domain: values.domain })
            actions.recheck()
            actions.recordManualSetup()
        },
        recordManualSetup: () => {
            if (!values.manualSetupRecorded) {
                actions.recordSetupMethod('manual')
            }
        },
    })),
])
